{
  "steps": [
    {
      "title": "შეავსე ბიურეტი",
      "text": "ონკანი დახურულია? ძაბრით ჩაასხი ტიტრანტი ნულოვან ნიშნულზე ოდნავ მაღლა.",
      "focus": ["p5", "p1", "p3"],
      "avoid": [],
      "markers": [
        {"part": "p5", "label": "შეამოწმე, დახურულია თუ არა", "tone": "brand"},
        {"part": "p1", "label": "აქ ჩაასხი ტიტრანტი", "tone": "brand"}
      ],
      "arrows": [],
      "tools": ["ტიტრანტი", "დამცავი სათვალე", "შესაბამისი დამცავი ხელთათმანები"],
      "warn": "ფოტოთი ონკანის დახურული მდგომარეობა და ნულოვანი ნიშნული ზუსტად ვერ დასტურდება; შეამოწმე ადგილზე. გამოიყენე რეაგენტის უსაფრთხოების ინსტრუქცია."
    },
    {
      "title": "მოხსენი ძაბრი",
      "text": "ძაბრი ტიტრაციამდე აუცილებლად მოხსენი. მისგან ჩამოსული წვეთები მოცულობას გააფუჭებს.",
      "focus": ["p1"],
      "avoid": ["p2"],
      "markers": [
        {"part": "p1", "label": "ამოსაღები ძაბრი", "tone": "brand"}
      ],
      "arrows": [
        {"part": "p1", "type": "move", "dir": "up"}
      ],
      "tools": [],
      "warn": "ძაბრი ფრთხილად ამოიღე; ბიურეტის სამაგრს არ შეეხო."
    },
    {
      "title": "წაიკითხე საწყისი მოცულობა",
      "text": "თვალი სითხის დონეზე დაიჭირე და წაიკითხე მენისკის ქვედა კიდე. ჩაიწერე ჟურნალში.",
      "focus": ["p3"],
      "avoid": [],
      "markers": [
        {"part": "p3", "label": "მენისკი — წაიკითხე თვალის დონეზე", "tone": "brand"}
      ],
      "arrows": [],
      "tools": ["ჟურნალი", "კალამი"],
      "warn": "ფოტოდან მოცულობის ზუსტი მნიშვნელობა არ იკითხება. საწყის ათვლამდე დარწმუნდი, რომ ბიურეტის ქვედა წვერი სითხითაა შევსებული და ჰაერის ბუშტები არ არის."
    },
    {
      "title": "დაამატე ინდიკატორი",
      "text": "კოლბაში ჩააწვეთე 2–3 წვეთი ფენოლფთალეინი და დადე თეთრ ფილაზე ონკანის ქვეშ.",
      "focus": ["p8", "p7", "p9"],
      "avoid": ["p6"],
      "markers": [
        {"part": "p8", "label": "საწვეთური — გადაამოწმე შიგთავსი", "tone": "neutral"},
        {"part": "p7", "label": "ინდიკატორი დაამატე კოლბაში", "tone": "brand"},
        {"part": "p9", "label": "კოლბის დასადგმელი თეთრი ფილა", "tone": "brand"}
      ],
      "arrows": [],
      "tools": ["ფენოლფთალეინის ინდიკატორი"],
      "warn": "p8 სავარაუდო ინდიკატორის ბოთლია მდებარეობისა და საწვეთური ფორმის მიხედვით, თუმცა მისი შიგთავსი ფოტოთი არ დასტურდება — შეამოწმე ეტიკეტი. 2–3 წვეთი ინსტრუქციის დოზაა და არა ფოტოდან დადგენილი. კოლბა უკვე ფილაზე ჩანს; გადაადგილებისას ბიურეტის წვერს არ შეეხო."
    },
    {
      "title": "ტიტრაცია",
      "text": "ონკანი ნელა გახსენი და კოლბა წრიულად ატრიალე. გაჩერდი, როცა ღია ვარდისფერი 30 წამს შენარჩუნდება.",
      "focus": ["p5", "p7"],
      "avoid": ["p6"],
      "markers": [
        {"part": "p5", "label": "აკონტროლე მიწოდება ონკანით", "tone": "brand"},
        {"part": "p7", "label": "ფრთხილად ატრიალე კოლბა", "tone": "brand"}
      ],
      "arrows": [
        {"part": "p7", "type": "rotate", "dir": "cw"}
      ],
      "tools": ["ტაიმერი"],
      "warn": "ონკანის გახსნის მიმართულება ფოტოდან ზუსტად არ დასტურდება; ძალა არ დაატანო. საბოლოო წერტილთან ტიტრანტი წვეთობით დაამატე და ფერის შენარჩუნებისას ონკანი დახურე. კოლბა ბიურეტის წვერს არ მიარტყა. 30 წამი ინსტრუქციის კრიტერიუმია."
    }
  ],
  "unknown_parts": []
}
